Steps:
[AUTH role=ADMIN_DEFAULT]
[GQL-OP wl]
query {
  whiteLabelingSettings(organizationId: "{{org_id}}" storeId: "{{STORE_ID}}" cultureName: "en-US") {
    footerLinks { title url priority childItems { title url priority } }
  }
}
[GQL-EXEC wl]

Assertions:
[ERRORS label=wl] errors[] empty
[DATA label=wl] data.whiteLabelingSettings.footerLinks[?title=Legal].priority = {{p_legal}}
[DATA label=wl] data.whiteLabelingSettings.footerLinks[?title=Help].priority = {{p_help}}
[COUNT label=wl] data.whiteLabelingSettings.footerLinks[?title=Legal].childItems.length = 2
[COUNT label=wl] data.whiteLabelingSettings.footerLinks[?title=Help].childItems.length = 2
[DATA label=wl] data.whiteLabelingSettings.footerLinks[?title=Legal].childItems[?title=Privacy Policy].priority = {{p_privacy}}
[DATA label=wl] data.whiteLabelingSettings.footerLinks[?title=Legal].childItems[?title=Privacy Policy].url is non-null

Steps:
[AUTH role=ADMIN_DEFAULT]
[GQL-OP wl]
query {
  whiteLabelingSettings(organizationId: "{{org_id}}" storeId: "{{STORE_ID}}" cultureName: "en-US") {
    mainMenuLinks { title url priority childItems { title url priority } }
  }
}
[GQL-EXEC wl]

Assertions:
[ERRORS label=wl] errors[] empty
[DATA label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Home].priority = {{p_home}}
[DATA label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Brands].priority = {{p_brands}}
[COUNT label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Brands].childItems.length = 3
[DATA label=wl] data.whiteLabelingSettings.mainMenuLinks[?title=Brands].childItems[?title=Tablets].priority = {{p_tablets}}

[SHAPE] no response in RESPONSES contains the path of OTHER_LOGO or the id {{other_org_id}}
[SHAPE] CROSS.logoUrl does not equal OTHER_LOGO — one organization's member does not read another organization's branding record
[SHAPE] the home page HTML and scripts contain no URL of another organization's logo
